const url = process.env.URL;
if (!url) throw new Error('Missing URL');
try {
  const res = await fetch(url, { headers: { 'User-Agent': 'Mozilla/5.0' } });
  if (!res.ok) throw new Error('Fetch failed with status ' + res.status);
  const text = await res.text();
  globalThis.rawBody = text;
  globalThis.fetchedUrl = url;
} catch (e) {
  throw new Error('fetch error: ' + e.message);
}

const raw = globalThis.rawBody;
if (typeof raw !== 'string') throw new Error('No raw body to parse');
const snippet = raw.slice(0, 200);
const sections = [{ index: 0, heading: '', text: snippet }];
globalThis.sectionsJson = JSON.stringify(sections);
